constexpr unsigned kGemmCubinSize = sizeof(kGemmCubin);
// The module holds four geometries: the plain kernel favours a deeper pipeline
// with a smaller tile (BK 64 / ST 3), the split-K kernel needs BK 128 so every
// contiguous kb slice starts on a 128-wide scale block (BK 64 / ST 2), the
// wide kernel (128x128 tile, GROUP_M=8 raster) trades 11.7 for 7.8 mB/flop and
// wins once the tile grid is large, and the b16 kernel (16x32 tile) covers the
// small-M band where 128-row tiles waste most of their rows.
constexpr int kSmemPlainBytes = 36864;  // ST(3) * (BM 128 + BN 64) * BK 64
constexpr int kSmemSkBytes = 49152;     // ST(2) * (BM 128 + BN 64) * BK 128
constexpr int kSmemWideBytes = 65536;   // ST(2) * (BM 128 + BN 128) * BK 128
constexpr int kSmemB16Bytes = 24576;    // ST(4) * (BM 16 + BN 32) * BK 128
constexpr int kTileM = 128;
constexpr int kTileN = 64;
constexpr int kB16TileM = 16;
constexpr int kB16TileN = 32;
// Cold-read A/B 2026-10-29 (NC=8 rotation): b16 wins 2 <= M <= 64 on every
// model shape (e.g. 16x16384x2560: 26.6us vs 40.7); wide wins M >= 512
// (4096x16384x2560: 464 vs 389 TF/s); mid band stays plain/split-K.
constexpr int kB16MaxM = 64;
constexpr int kWideMinM = 512;
constexpr int kWideMinCtas = 376;  // 2 CTAs/SM of 188; thinner grids keep split-K

using ModuleLoadFn = CUresult (*)(CUmodule*, const void*);
using GetFuncFn = CUresult (*)(CUfunction*, CUmodule, const char*);
using SetAttrFn = CUresult (*)(CUfunction, CUfunction_attribute, int);
using LaunchFn = CUresult (*)(CUfunction, unsigned, unsigned, unsigned,
                              unsigned, unsigned, unsigned, unsigned,
                              CUstream, void**, void**);

struct GemmImage {
  CUmodule mod = nullptr;
  CUfunction fn = nullptr;
  CUfunction sk_fn = nullptr;
  CUfunction reduce_fn = nullptr;
  CUfunction wide_fn = nullptr;
  CUfunction b16_fn = nullptr;
  LaunchFn launch_fn = nullptr;

  CUresult launch(unsigned gx, unsigned gy, CUstream s, void** p) const {
    return launch_fn(fn, gx, gy, 1, 256, 1, 1, kSmemPlainBytes, s, p, nullptr);
  }

  CUresult launch_wide(unsigned gx, unsigned gy, CUstream s, void** p) const {
    return launch_fn(wide_fn, gx, gy, 1, 256, 1, 1, kSmemWideBytes, s, p, nullptr);
  }

  CUresult launch_b16(unsigned gx, unsigned gy, CUstream s, void** p) const {
    return launch_fn(b16_fn, gx, gy, 1, 128, 1, 1, kSmemB16Bytes, s, p, nullptr);
  }

  CUresult launch_sk(unsigned gx, unsigned gy, unsigned gz, CUstream s, void** p) const {
    return launch_fn(sk_fn, gx, gy, gz, 256, 1, 1, kSmemSkBytes, s, p, nullptr);
  }

  CUresult launch_reduce(unsigned blocks, CUstream s, void** p) const {
    return launch_fn(reduce_fn, blocks, 1, 1, 256, 1, 1, 0, s, p, nullptr);
  }

  GemmImage() {
    void* h = dlopen("libcuda.so.1", RTLD_NOW | RTLD_GLOBAL);
    if (h == nullptr) {
      printf("e3m4 gemm: cannot dlopen libcuda.so.1\n");
      return;
    }
    auto load = reinterpret_cast<ModuleLoadFn>(dlsym(h, "cuModuleLoadData"));
    auto getf = reinterpret_cast<GetFuncFn>(dlsym(h, "cuModuleGetFunction"));
    auto setattr = reinterpret_cast<SetAttrFn>(dlsym(h, "cuFuncSetAttribute"));
    if (load == nullptr || getf == nullptr || setattr == nullptr) {
      printf("e3m4 gemm: cuModule symbols missing\n");
      return;
    }
    if (load(&mod, kGemmCubin) != CUDA_SUCCESS) {
      mod = nullptr;
      printf("e3m4 gemm: cuModuleLoadData failed\n");
      return;
    }
    launch_fn = reinterpret_cast<LaunchFn>(dlsym(h, "cuLaunchKernel"));
    if (launch_fn == nullptr) {
      printf("e3m4 gemm: cuLaunchKernel missing\n");
      return;
    }
    if (getf(&fn, mod, "sm120_fp8_e3m4_gemm") != CUDA_SUCCESS) {
      fn = nullptr;
      printf("e3m4 gemm: symbol not found\n");
      return;
    }
    setattr(fn, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, kSmemPlainBytes);
    // Split-K is an optimisation for shapes whose tile grid cannot fill the
    // device; if either symbol is absent the caller just uses the plain path.
    if (getf(&sk_fn, mod, "sm120_fp8_e3m4_gemm_sk") == CUDA_SUCCESS) {
      setattr(sk_fn, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, kSmemSkBytes);
      if (getf(&reduce_fn, mod, "sm120_fp8_e3m4_sk_reduce") != CUDA_SUCCESS) {
        reduce_fn = nullptr;
        sk_fn = nullptr;
      }
    } else {
      sk_fn = nullptr;
    }
    // Wide and b16 are optional bands too: an older cubin without them
    // silently falls back to the plain/split-K dispatch.
    if (getf(&wide_fn, mod, "sm120_fp8_e3m4_gemm_wide") == CUDA_SUCCESS) {
      setattr(wide_fn, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
              kSmemWideBytes);
    } else {
      wide_fn = nullptr;
    }
    if (getf(&b16_fn, mod, "sm120_fp8_e3m4_gemm_b16") == CUDA_SUCCESS) {
      setattr(b16_fn, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES,
              kSmemB16Bytes);
    } else {
      b16_fn = nullptr;
    }
  }
};

GemmImage& image() {
  static GemmImage img;
  return img;
}

}  // namespace

// One 128x64 tile grid launches ceil(M/128)*ceil(N/64) CTAs. While M fits in
// one tile that is only N/64 CTAs, and the 188 SMs are not filled: the n=512
// k/v projections ran at 64 GB/s and n=2560 x k=6144 at 333 GB/s against a
// 1754 GB/s copy roofline. Splitting the K loop across gridDim.z adds CTAs at
// the cost of an fp32 partial round trip, so the best split count shrinks as
// the tiles already on offer grow.
//
// The split must divide nk = K/128: slices are contiguous scale blocks, and an
// uneven partition is only balanced when every CTA gets the same number. A
// dense divisor sweep over the five model shapes (4-512 tokens) says the
// optimum sits at ~448 resident CTAs and is a divisor, not a power of two --
// rounding 5 up to 8 for nk=40 costs ~10 % because it leaves a remainder slice
// idle. So: take the smallest divisor of nk that reaches the target, but never
// one whose partial buffer exceeds a fixed traffic budget, since past that the
// write-then-read of fp32 partials dominates the kernel it is meant to speed up.
static int pick_splits(int M, int N, int K) {
  constexpr int kTargetCtas = 448;
  constexpr long long kPartialBudgetBytes = 6LL * 1024 * 1024;
  const int nk = K / 128;
  const int tiles = ((M + kTileM - 1) / kTileM) * ((N + kTileN - 1) / kTileN);
  const int need = (kTargetCtas + tiles - 1) / tiles;
  if (nk <= 1 || need <= 1) return 1;
  int fits = 1;      // largest divisor still inside the partial budget
  int reached = 0;   // smallest divisor that meets the CTA target
  for (int d = 2; d <= nk; ++d) {
    if (nk % d != 0) continue;
    // Divisors ascend, so the budget test can stop the search instead of
    // skipping the rest of them.
    if (static_cast<long long>(d) * M * N * 4 > kPartialBudgetBytes) break;
    fits = d;
    if (d >= need) {
      reached = d;
      break;
    }
  }
  return reached != 0 ? reached : fits;
}

struct Sm120Fp8E3m4Gemm {
  static void
  run(const tvm::ffi::TensorView a,
      const tvm::ffi::TensorView b,
      const tvm::ffi::TensorView a_s,
      const tvm::ffi::TensorView w_s,
      const tvm::ffi::TensorView out) {
    using namespace host;
    auto device = SymbolicDevice{};
    device.set_options<kDLCUDA>();
    const int M = static_cast<int>(a.shape()[0]);
    const int K = static_cast<int>(a.shape()[1]);
    const int N = static_cast<int>(b.shape()[0]);
    TensorMatcher({M, K}).with_dtype<fp8_e4m3_t>().verify(a);
    TensorMatcher({N, K}).verify(b);
    TensorMatcher({M, K / 128}).with_dtype<fp32_t>().with_device(device).verify(a_s);
    TensorMatcher({N / 128, K / 128}).with_dtype<fp32_t>().with_device(device).verify(w_s);

    host::RuntimeCheck(M > 0, "empty M");
    auto& img = image();
    host::RuntimeCheck(img.fn != nullptr, "sm120_fp8_e3m4_gemm image unavailable");
    host::RuntimeCheck(K % 128 == 0, "e3m4 gemm needs K % 128 == 0, got ", K);
    host::RuntimeCheck(N % kTileN == 0, "e3m4 gemm needs N % ", kTileN, " == 0, got ", N);

    void* pa = a.data_ptr();
    void* pb = b.data_ptr();
    void* pc = out.data_ptr();
    void* psa = a_s.data_ptr();
    void* psw = w_s.data_ptr();
    int m = M, n = N, k = K;
    auto stream = host::LaunchKernel::resolve_device(device.unwrap());
    const unsigned gx = static_cast<unsigned>((M + kTileM - 1) / kTileM);
    const unsigned gy = static_cast<unsigned>((N + kTileN - 1) / kTileN);

    // Small-M band: the 16x32 tile keeps 2..64-token decodes off the 128-row
    // tile that wastes 87-99% of its rows (cold: 26.6 vs 40.7us at 16x16384x2560).
    if (img.b16_fn != nullptr && M <= kB16MaxM && N % kB16TileN == 0) {
      void* params[] = {&pa, &pb, &pc, &psa, &psw, &m, &n, &k};
      CUresult rc = img.launch_b16(static_cast<unsigned>((M + kB16TileM - 1) / kB16TileM),
                                   static_cast<unsigned>(N / kB16TileN),
                                   static_cast<CUstream>(stream), params);
      host::RuntimeCheck(rc == CUDA_SUCCESS, "gemm_b16 cuLaunchKernel failed: ",
                         static_cast<int>(rc));
      return;
    }
    // Prefill band: the 128x128 tile is traffic-lean but needs a deep grid.
    if (img.wide_fn != nullptr && M >= kWideMinM &&
        ((M + kTileM - 1) / kTileM) * ((N + 127) / 128) >= kWideMinCtas) {
      void* params[] = {&pa, &pb, &pc, &psa, &psw, &m, &n, &k};
      CUresult rc = img.launch_wide(static_cast<unsigned>((M + kTileM - 1) / kTileM),
                                    static_cast<unsigned>((N + 127) / 128),
                                    static_cast<CUstream>(stream), params);
      host::RuntimeCheck(rc == CUDA_SUCCESS, "gemm_wide cuLaunchKernel failed: ",
                         static_cast<int>(rc));
      return;
    }

    const int splits = img.sk_fn != nullptr ? pick_splits(M, N, K) : 1;
    if (splits <= 1) {
      void* params[] = {&pa, &pb, &pc, &psa, &psw, &m, &n, &k};
      CUresult rc = img.launch(gx, gy, static_cast<CUstream>(stream), params);
      host::RuntimeCheck(rc == CUDA_SUCCESS, "cuLaunchKernel failed: ", static_cast<int>(rc));
      return;
    }

    auto ws = host::ffi::alloc_workspace_tensor(
        static_cast<size_t>(splits) * M * N * sizeof(float), a.device());
    void* pp = ws.data_ptr();
    void* params[] = {&pa, &pb, &pc, &pp, &psa, &psw, &m, &n, &k};
    CUresult rc = img.launch_sk(gx, gy, static_cast<unsigned>(splits),
                                 static_cast<CUstream>(stream), params);
    host::RuntimeCheck(rc == CUDA_SUCCESS, "gemm_sk cuLaunchKernel failed: ",
                       static_cast<int>(rc));
    long long size = static_cast<long long>(M) * N;
    int sp = splits;
    void* rparams[] = {&pc, &pp, &size, &sp};
    rc = img.launch_reduce(static_cast<unsigned>((size + 255) / 256),
                           static_cast<CUstream>(stream), rparams);
    host::RuntimeCheck(rc == CUDA_SUCCESS, "gemm_sk reduce launch failed: ",
                       static_cast<int>(rc));
  }
};

}  // namespace sglang
